<?php
require __DIR__ . '/../app/bootstrap.php';
$u=require_auth();$id=(int)($_GET['id']??0);
$s=$db->prepare('SELECT i.*,r.name reseller_name,r.email reseller_email,o.domain,p.name package_name FROM invoices i JOIN resellers r ON r.id=i.reseller_id LEFT JOIN orders o ON o.id=i.order_id LEFT JOIN packages p ON p.id=o.package_id WHERE i.id=? LIMIT 1');$s->execute([$id]);$i=$s->fetch();
if(!$i) {http_response_code(404);exit('Invoice not found.');}
if($u['role']==='reseller'){$q=$db->prepare('SELECT id FROM resellers WHERE user_id=?');$q->execute([$u['id']]);if((int)$q->fetchColumn()!==(int)$i['reseller_id']){http_response_code(403);exit('Forbidden');}}
$s=$db->prepare('SELECT * FROM invoice_items WHERE invoice_id=? ORDER BY id');$s->execute([$id]);$items=$s->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($i['invoice_number'])?> — SkyNoc</title><style>body{margin:0;background:#f3f4f6;font-family:Inter,system-ui,sans-serif;color:#111827}.sheet{max-width:800px;margin:30px auto;background:#fff;padding:35px;border-radius:16px}.head{display:flex;justify-content:space-between;gap:20px}.muted{color:#64748b}table{width:100%;border-collapse:collapse;margin-top:30px}td,th{padding:12px;border-bottom:1px solid #e5e7eb;text-align:left}.total{text-align:right;font-size:22px;font-weight:800;margin-top:20px}.paid{color:#166534;font-weight:800}@media(max-width:600px){.sheet{margin:0;padding:22px;border-radius:0}.head{flex-direction:column}}</style></head><body><main class="sheet"><div class="head"><div><h1>SkyNoc</h1><p class="muted">WHMCS License Services</p></div><div><b><?=e($i['invoice_number'])?></b><br><?=e($i['created_at'])?><br><span class="paid"><?=e(strtoupper($i['status']))?></span></div></div><hr><p><b>Bill To:</b><br><?=e($i['reseller_name'])?><br><?=e($i['reseller_email'])?></p><table><tr><th>Description</th><th>Qty</th><th>Amount</th></tr><?php foreach($items as $x):?><tr><td><?=e($x['description'])?><?=($i['domain']?'<br><small class="muted">'.e($i['domain']).'</small>':'')?></td><td><?=e((string)$x['quantity'])?></td><td>$<?=number_format((float)$x['amount'],2)?></td></tr><?php endforeach;?></table><div class="total">Subtotal: $<?=number_format((float)$i['subtotal'],2)?><br>Discount: -$<?=number_format((float)$i['discount'],2)?><br>Total: $<?=number_format((float)$i['total'],2)?></div><p class="muted">Thank you for using SkyNoc.</p></main></body></html>